const outputs = { seo_output: null, wp_output: null, automation_output: null, monetization_output: null };
for (const item of $input.all()) {
  const o = item.json.agent_output;
  if (!o || !o.agent) continue;
  if (o.agent === 'seo') outputs.seo_output = o;
  if (o.agent === 'wp') outputs.wp_output = o;
  if (o.agent === 'automation') outputs.automation_output = o;
  if (o.agent === 'monetization') outputs.monetization_output = o;
}
const base = $input.first().json;
return [{ json: { mission: base.mission, context: base.context, data: base.data, router: base.router, routing_summary: base.routing_summary, iteration: base.iteration ?? 0, qa_fixes_required: base.qa_fixes_required ?? [], ...outputs } }];

